// Subscribe once, for example in the form constructor
dgvOrders.CellClick += DgvOrders_CellClick;

private void DgvOrders_CellClick(object sender, DataGridViewCellEventArgs e)
{
    if (e.RowIndex >= 0)
    {
        MessageBox.Show("Row " + e.RowIndex + ", column " + e.ColumnIndex);
    }
}

// Subscribe once, for example in the form constructor
dgvOrders.CellValueChanged += DgvOrders_CellValueChanged;

private void DgvOrders_CellValueChanged(object sender, DataGridViewCellEventArgs e)
{
    if (e.RowIndex >= 0)
    {
        this.Text = "Edited row " + e.RowIndex;
    }
}

// Subscribe once, for example in the form constructor
dgvOrders.CellEndEdit += DgvOrders_CellEndEdit;

private void DgvOrders_CellEndEdit(object sender, DataGridViewCellEventArgs e)
{
    MessageBox.Show("New value: " + dgvOrders.Rows[e.RowIndex].Cells[e.ColumnIndex].Value);
}

// Subscribe once, for example in the form constructor
dgvOrders.SelectionChanged += DgvOrders_SelectionChanged;

private void DgvOrders_SelectionChanged(object sender, EventArgs e)
{
    this.Text = "Selected rows: " + dgvOrders.SelectedRows.Count;
}

// Subscribe once, for example in the form constructor
dgvOrders.DataError += DgvOrders_DataError;

private void DgvOrders_DataError(object sender, DataGridViewDataErrorEventArgs e)
{
    MessageBox.Show("Invalid value in row " + e.RowIndex + ": " + e.Exception.Message);
    e.ThrowException = false;
}

// Subscribe once, for example in the form constructor
dgvOrders.CellFormatting += DgvOrders_CellFormatting;

private void DgvOrders_CellFormatting(object sender, DataGridViewCellFormattingEventArgs e)
{
    if (e.Value is decimal amount && amount < 0)
    {
        e.CellStyle.ForeColor = Color.Red;
    }
}

